{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required payload fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list) or not all(isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be a list of strings")

    required = set(required_symbols)
    by_id = {}
    source_order = {}
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node missing required field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id == "":
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be null or a string")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if not ((isinstance(utility, int) or isinstance(utility, float)) and not isinstance(utility, bool)):
            raise ValueError("utility must be numeric")
        by_id[node_id] = node
        source_order[node_id] = index

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]
    if roots[0]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node["id"]: [] for node in nodes}
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("parent id does not exist")
        if by_id[parent]["depth"] + 1 != node["depth"]:
            raise ValueError("child depth must be parent depth plus one")
        children[parent].append(node_id)

    visited = set()
    stack = [(root_id, set())]
    while stack:
        node_id, ancestors = stack.pop()
        if node_id in ancestors:
            raise ValueError("cycle in tree")
        if node_id in visited:
            raise ValueError("node has multiple paths")
        visited.add(node_id)
        next_ancestors = set(ancestors)
        next_ancestors.add(node_id)
        for child_id in children[node_id]:
            stack.append((child_id, next_ancestors))
    if len(visited) != len(nodes):
        raise ValueError("tree is not connected")

    present_symbols = {node["symbol"] for node in nodes}
    if not required.issubset(present_symbols):
        raise ValueError("required symbol is not represented")

    retained = {node["id"] for node in nodes}
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))

    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node_id == root_id:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        next_retained = retained - {node_id}
        represented = {by_id[retained_id]["symbol"] for retained_id in next_retained}
        if not required.issubset(represented):
            continue

        retained = next_retained
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
